import{c as t,Q as a,j as n,m as i}from"./chunks/framework.BXc4yaFE.js";const p=JSON.parse('{"title":"ReAct: Synergizing Reasoning and Acting in Language Models","description":"","frontmatter":{"url":"https://arxiv.org/abs/2210.03629","title":"ReAct: Synergizing Reasoning and Acting in Language Models","archived_date":"2026-06-09T00:00:00.000Z","arxiv_id":2210.03629,"authors":["Shunyu Yao","Jeffrey Zhao","Dian Yu","Nan Du","Izhak Shafran","Karthik Narasimhan","Yuan Cao"],"pdf_path":"pdfs/2210.03629.pdf","published_date":"2022-10-06T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2022-10-06-react-synergizing-reasoning-acting-2210-03629.md","filePath":"research/papers/2022-10-06-react-synergizing-reasoning-acting-2210-03629.md","lastUpdated":1785909234000}'),o={name:"research/papers/2022-10-06-react-synergizing-reasoning-acting-2210-03629.md"};function r(s,e,l,c,h,g){return a(),n("div",null,[...e[0]||(e[0]=[i(`<h2 id="abstract" tabindex="-1">Abstract <a class="header-anchor" href="#abstract" aria-label="Permalink to &quot;Abstract&quot;">​</a></h2><p>While large language models (LLMs) have demonstrated impressive capabilities across tasks in language understanding and interactive decision making, their abilities for reasoning (e.g. chain-of-thought prompting) and acting (e.g. action plan generation) have primarily been studied as separate topics. In this paper, we explore the use of LLMs to generate both reasoning traces and task-specific actions in an interleaved manner, allowing for greater synergy between the two: reasoning traces help the model induce, track, and update action plans as well as handle exceptions, while actions allow it to interface with external sources, such as knowledge bases or environments, to gather additional information. We apply our approach, named ReAct, to a diverse set of language and decision making tasks and demonstrate its effectiveness over state-of-the-art baselines, as well as improved human interpretability and trustworthiness over methods without reasoning or acting components. Concretely, on question answering (HotpotQA) and fact verification (Fever), ReAct overcomes issues of hallucination and error propagation prevalent in chain-of-thought reasoning by interacting with a simple Wikipedia API, and generates human-like task-solving trajectories that are more interpretable than baselines without reasoning traces. On two interactive decision making benchmarks (ALFWorld and WebShop), ReAct outperforms imitation and reinforcement learning methods by an absolute success rate of 34% and 10% respectively, while being prompted with only one or two in-context examples.</p><h2 id="主要貢獻" tabindex="-1">主要貢獻 <a class="header-anchor" href="#主要貢獻" aria-label="Permalink to &quot;主要貢獻&quot;">​</a></h2><ul><li><strong>ReAct 框架</strong>：讓 LLM 以交錯方式（interleaved manner）同時生成推理軌跡（reasoning traces）和任務特定行動（actions），實現推理與行動的協同增效。</li><li><strong>推理輔助行動</strong>：推理軌跡幫助模型推導、追蹤、更新行動計畫，並處理例外情況；行動讓模型與外部知識庫或環境互動以獲取額外資訊。</li><li><strong>克服幻覺問題</strong>：在 HotpotQA 和 Fever 上，ReAct 透過與 Wikipedia API 互動，克服了 chain-of-thought 推理中常見的幻覺和錯誤傳播問題。</li><li><strong>互動式決策表現</strong>：在 ALFWorld 和 WebShop 兩個互動決策 benchmark 上，ReAct 分別以 34% 和 10% 的絕對成功率優於模仿學習和強化學習方法，且僅使用一至二個 in-context 範例。</li><li><strong>可解釋性與可信賴性</strong>：生成類似人類的任務解決軌跡，相較於無推理追蹤的方法，具備更高的人類可解釋性和可信賴性。</li><li><strong>影響力</strong>：ReAct 成為後續 agent 框架（LangChain、AutoGPT 等）的基礎設計模式，是 LLM agent 領域最具影響力的論文之一。</li></ul><h2 id="論文全文" tabindex="-1">論文全文 <a class="header-anchor" href="#論文全文" aria-label="Permalink to &quot;論文全文&quot;">​</a></h2><blockquote><p>HTML 全文暫不可用（arxiv HTML 轉換尚未完成）。以下為完整摘要頁面資訊及擴充內容。</p></blockquote><p><strong>Title</strong>: ReAct: Synergizing Reasoning and Acting in Language Models <strong>Authors</strong>: Shunyu Yao, Jeffrey Zhao, Dian Yu, Nan Du, Izhak Shafran, Karthik Narasimhan, Yuan Cao <strong>arXiv ID</strong>: 2210.03629 <strong>Published</strong>: 2022-10-06 <strong>Venue</strong>: ICLR 2023 <strong>URL</strong>: <a href="https://arxiv.org/abs/2210.03629" target="_blank" rel="noreferrer">https://arxiv.org/abs/2210.03629</a><strong>Project site</strong>: <a href="https://react-lm.github.io/" target="_blank" rel="noreferrer">https://react-lm.github.io/</a></p><h3 id="full-abstract" tabindex="-1">Full Abstract <a class="header-anchor" href="#full-abstract" aria-label="Permalink to &quot;Full Abstract&quot;">​</a></h3><p>While large language models (LLMs) have demonstrated impressive capabilities across tasks in language understanding and interactive decision making, their abilities for reasoning (e.g. chain-of-thought prompting) and acting (e.g. action plan generation) have primarily been studied as separate topics. In this paper, we explore the use of LLMs to generate both reasoning traces and task-specific actions in an interleaved manner, allowing for greater synergy between the two: reasoning traces help the model induce, track, and update action plans as well as handle exceptions, while actions allow it to interface with external sources, such as knowledge bases or environments, to gather additional information. We apply our approach, named ReAct, to a diverse set of language and decision making tasks and demonstrate its effectiveness over state-of-the-art baselines, as well as improved human interpretability and trustworthiness over methods without reasoning or acting components. Concretely, on question answering (HotpotQA) and fact verification (Fever), ReAct overcomes issues of hallucination and error propagation prevalent in chain-of-thought reasoning by interacting with a simple Wikipedia API, and generates human-like task-solving trajectories that are more interpretable than baselines without reasoning traces. On two interactive decision making benchmarks (ALFWorld and WebShop), ReAct outperforms imitation and reinforcement learning methods by an absolute success rate of 34% and 10% respectively, while being prompted with only one or two in-context examples.</p><h3 id="core-methodology" tabindex="-1">Core Methodology <a class="header-anchor" href="#core-methodology" aria-label="Permalink to &quot;Core Methodology&quot;">​</a></h3><p><strong>The ReAct paradigm</strong> interleaves Thought-Action-Observation triples:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Thought: I need to find information about X.</span></span>
<span class="line"><span>Action: Search[X]</span></span>
<span class="line"><span>Observation: X is a concept that...</span></span>
<span class="line"><span>Thought: Based on this, I can conclude Y.</span></span>
<span class="line"><span>Action: Finish[Y]</span></span></code></pre></div><p>This interleaving allows:</p><ol><li><strong>Reasoning traces</strong> to ground action planning in observed context</li><li><strong>Actions</strong> to ground reasoning in external reality (Wikipedia, environment)</li><li><strong>Dynamic replanning</strong> when actions produce unexpected observations</li></ol><h3 id="key-comparisons" tabindex="-1">Key Comparisons <a class="header-anchor" href="#key-comparisons" aria-label="Permalink to &quot;Key Comparisons&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Method</th><th>Reasoning</th><th>Acting</th><th>External Info</th></tr></thead><tbody><tr><td>Chain-of-Thought (CoT)</td><td>Yes</td><td>No</td><td>No</td></tr><tr><td>Act-only</td><td>No</td><td>Yes</td><td>Yes</td></tr><tr><td>ReAct</td><td>Yes (interleaved)</td><td>Yes</td><td>Yes</td></tr></tbody></table><p><strong>ReAct advantages over CoT</strong>: Reduces hallucination by grounding reasoning in retrieved facts; enables error recovery through iterative action-observation loops.</p><p><strong>ReAct advantages over Act-only</strong>: More interpretable trajectories; better long-horizon planning through explicit reasoning traces.</p><h3 id="experimental-results" tabindex="-1">Experimental Results <a class="header-anchor" href="#experimental-results" aria-label="Permalink to &quot;Experimental Results&quot;">​</a></h3><p><strong>Knowledge-intensive QA tasks</strong>:</p><ul><li>HotpotQA: ReAct outperforms Act-only and CoT, with fewer hallucinations</li><li>Fever (fact verification): ReAct achieves higher accuracy by verifying claims against Wikipedia</li></ul><p><strong>Interactive decision making</strong>:</p><ul><li>ALFWorld (text-based game): +34% success rate vs. BUTLER (imitation learning baseline)</li><li>WebShop (simulated e-commerce): +10% success rate vs. IL/RL baselines</li></ul><p><strong>Human evaluation</strong>: ReAct trajectories rated as more interpretable and trustworthy than Act-only or CoT trajectories.</p><h3 id="why-react-matters" tabindex="-1">Why ReAct Matters <a class="header-anchor" href="#why-react-matters" aria-label="Permalink to &quot;Why ReAct Matters&quot;">​</a></h3><p>ReAct established the foundational &quot;think-then-act&quot; paradigm for LLM agents that has since been adopted by virtually every major agent framework (LangChain, LlamaIndex, AutoGPT, OpenAgents, etc.). It showed that:</p><ol><li>Reasoning and acting are complementary, not competing, capabilities</li><li>External tools can ground LLM reasoning in factual reality</li><li>Thought traces serve as an implicit scratchpad for multi-step problem solving</li><li>Few-shot prompting is sufficient to elicit ReAct behavior in capable LLMs</li></ol><p>The paper directly inspired Reflexion (which adds verbal self-reflection), Toolformer (which learns tool use), and many subsequent agent architectures that use tool-augmented reasoning.</p>`,28)])])}const u=t(o,[["render",r]]);export{p as __pageData,u as default};
